def get_median(arr1, arr2, n):
    # Merge the two sorted lists
    merged = []
    i = j = 0

    while i < n and j < n:
        if arr1[i] <= arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1

    # Add remaining elements
    while i < n:
        merged.append(arr1[i])
        i += 1

    while j < n:
        merged.append(arr2[j])
        j += 1

    # Calculate median
    if n % 2 == 0:
        median = (merged[n // 2 - 1] + merged[n // 2]) / 2
    else:
        median = merged[n // 2]

    return median
